status.windowCss:
#us-float, #us-prompt-bubble-window, .us-box, .hx-scroll {
  --us-float-bg: #121815;
  --us-float-fg: #cdd1cb;
  --us-float-border: #1f2823;
  --us-float-muted: #7b837d;
  --us-float-primary: #cdd1cb;
  --us-float-primary-fg: #121815;
  --us-float-secondary: #2c3630;
  --us-float-accent: #2c3630;
  scrollbar-color: #2c3630 #121815 !important;
  scrollbar-width: thin !important;
}
#us-float .us-f-title, #us-float .us-tab, #us-float .us-scene-button {
  font-family: 'Courier New', ui-monospace, monospace;
}
#us-float .us-tab { border-radius: 3px !important; padding: 4px 12px !important; margin: 0 2px !important; }
#us-float .us-scene-button { border-radius: 3px !important; }
#us-float ::-webkit-scrollbar, .us-box ::-webkit-scrollbar, .hx-scroll::-webkit-scrollbar, .hx-scroll ::-webkit-scrollbar { width: 6px !important; height: 6px !important; }
#us-float ::-webkit-scrollbar-track, .us-box ::-webkit-scrollbar-track, .hx-scroll::-webkit-scrollbar-track, .hx-scroll ::-webkit-scrollbar-track { background: #121815 !important; }
#us-float ::-webkit-scrollbar-thumb, .us-box ::-webkit-scrollbar-thumb, .hx-scroll::-webkit-scrollbar-thumb, .hx-scroll ::-webkit-scrollbar-thumb { background: #2c3630 !important; border-radius: 3px !important; }
#us-float ::-webkit-scrollbar-thumb:hover, .us-box ::-webkit-scrollbar-thumb:hover, .hx-scroll::-webkit-scrollbar-thumb:hover, .hx-scroll ::-webkit-scrollbar-thumb:hover { background: #7b837d !important; }
